                    "SchemaId");
            }

            foreach (var relationship in relationshipBuffers.TableKeyRelationships ?? Enumerable.Empty<TableKeyRelationships>())
            {
                relationship.Row.Table = RequireTarget(
                    loadIndexes.TableListById,
