                    "TableKey",
                    relationship.Row.Id,
                    "TableId");
            }

            foreach (var relationship in relationshipBuffers.TableKeyFieldRelationships ?? Enumerable.Empty<TableKeyFieldRelationships>())
            {
                relationship.Row.Field = RequireTarget(
                    loadIndexes.FieldListById,
                    relationship.FieldId,
                    "TableKeyField",
                    relationship.Row.Id,
                    "FieldId");
            }

            foreach (var relationship in relationshipBuffers.TableKeyFieldRelationships ?? Enumerable.Empty<TableKeyFieldRelationships>())
            {
                relationship.Row.TableKey = RequireTarget(
                    loadIndexes.TableKeyListById,
                    relationship.TableKeyId,
                    "TableKeyField",
                    relationship.Row.Id,
                    "TableKeyId");
            }

            foreach (var relationship in relationshipBuffers.TableRelationshipRelationships ?? Enumerable.Empty<TableRelationshipRelationships>())
            {
                relationship.Row.SourceTable = RequireTarget(
                    loadIndexes.TableListById,
                    relationship.SourceTableId,
                    "TableRelationship",
                    relationship.Row.Id,
                    "SourceTableId");
            }

            foreach (var relationship in relationshipBuffers.TableRelationshipRelationships ?? Enumerable.Empty<TableRelationshipRelationships>())
            {
                relationship.Row.TargetTable = RequireTarget(
                    loadIndexes.TableListById,
                    relationship.TargetTableId,
                    "TableRelationship",
                    relationship.Row.Id,
                    "TargetTableId");
            }

            foreach (var relationship in relationshipBuffers.TableRelationshipFieldRelationships ?? Enumerable.Empty<TableRelationshipFieldRelationships>())
            {
                relationship.Row.SourceField = RequireTarget(
                    loadIndexes.FieldListById,
                    relationship.SourceFieldId,
