            }

            foreach (var relationship in relationshipBuffers.TableRelationshipFieldRelationships ?? Enumerable.Empty<TableRelationshipFieldRelationships>())
            {
                relationship.Row.TargetField = RequireTarget(
                    loadIndexes.FieldListById,
                    relationship.TargetFieldId,
                    "TableRelationshipField",
                    relationship.Row.Id,
                    "TargetFieldId");
            }

        }

        private static readonly string[] ShardFileNames =
        {
            "Field.xml",
            "FieldDataTypeDetail.xml",
            "Schema.xml",
            "System.xml",
            "Table.xml",
            "TableKey.xml",
            "TableKeyField.xml",
